import { useState } from "react";

export default function StudentResultApp() {
  const [name, setName] = useState("");
  const [marks, setMarks] = useState("");
  const [result, setResult] = useState(null);

  const handleCheck = () => {
    if (!name || !marks) return;
    const num = Number(marks);
    setResult({ status: num >= 33 ? "Pass" : "Fail", score: num });
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-600 to-indigo-700 p-4">
      <div className="w-full max-w-md bg-white/10 backdrop-blur-xl p-6 rounded-2xl shadow-2xl border border-white/20">
        <h1 className="text-3xl font-bold text-white text-center mb-4 tracking-wide">Student Result System</h1>

        <div className="flex flex-col gap-3">
          <input
            type="text"
            placeholder="Enter student name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="p-3 rounded-xl bg-white/20 text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-pink-400"
          />

          <input
            type="number"
            placeholder="Enter marks"
            value={marks}
            onChange={(e) => setMarks(e.target.value)}
            className="p-3 rounded-xl bg-white/20 text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-teal-400"
          />

          <button
            onClick={handleCheck}
            className="mt-2 bg-pink-500 hover:bg-pink-600 text-white py-3 rounded-xl text-lg font-semibold transition-all active:scale-95 shadow-lg"
          >
            Check Result
          </button>
        </div>

        {result && (
          <div className="mt-6 p-4 rounded-xl text-center bg-white/20 text-white font-medium backdrop-blur-lg border border-white/20 animate-fadeIn">
            <p className="text-xl">Name: {name}</p>
            <p className="text-xl">Marks: {result.score}</p>
            <p className={`text-2xl font-bold mt-2 ${result.status === "Pass" ? "text-green-300" : "text-red-300"}`}>
              {result.status}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
